# each from the first to the last day of its month and named yyyy-mm. A month already named, or
# overlapping a period of the sheet, is left out. Answers how many were made.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: generate
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
